namespace Vnecoms\Quotation\Model;

use Vnecoms\Quotation\Api\Data\MessageInterface;
use Magento\Framework\App\ObjectManager;

/**
 * Class Message
 * @package Vnecoms\Quotation\Model
 * @method string getAuthor()
 * @method Message setAuthor($author)
 * @method string getMessage()
 * @method Message setMessage($message)
 * @method string getCreatedAt()
 * @method Message setCreatedAt($time)
 */
class Message extends \Magento\Framework\Model\AbstractModel implements MessageInterface
{
    const TYPE_CUSTOMER = 0;
    const TYPE_ADMIN    = 1;
    const TYPE_VENDOR   = 2;

    /**
     * Prefix of model events names
     *
     * @var string
     */
    protected $_eventPrefix = 'quotation_message';

    /**
     * Parameter name in event
     *
     * In observe method you can use $observer->getEvent()->getObject() in this case
     *
     * @var string
     */
    protected $_eventObject = 'message';

    /**
     * @var \Vnecoms\Quotation\Model\Quote|null
     */
    protected $quote;


    /**
     * @var \Magento\Framework\Stdlib\DateTime\TimezoneInterface
     */
    protected $timezone;

    /**
     * @var \Magento\Catalog\Model\ImageUploader
     */
    protected $imageUploader;

    public function __construct
    (
        \Magento\Framework\Model\Context $context,
        \Magento\Framework\Registry $registry,
        \Magento\Framework\Stdlib\DateTime\TimezoneInterface $timezone,
        \Magento\Framework\Model\ResourceModel\AbstractResource $resource = null,
        \Magento\Framework\Data\Collection\AbstractDb $resourceCollection = null,
        array $data = []
    )
    {
        $this->timezone = $timezone;
        parent::__construct($context, $registry, $resource, $resourceCollection, $data);
    }

    /**
     * Get message_id
     * @return string
     */
    public function getMessageId()
    {
        return $this->getData(self::MESSAGE_ID);
    }

    /**
     * Set message_id
     * @param string $messageId
     * @return \Vnecoms\Quotation\Api\Data\MessageInterface
     */
    public function setMessageId($messageId)
    {
        return $this->setData(self::MESSAGE_ID, $messageId);
    }

    /**
     * Get name
     * @return string
     */
    public function getName()
    {
        return $this->getData(self::NAME);
    }

    /**
     * Get quote_id
     * @return string
     */
    public function getQuoteId()
    {
        return $this->getData('quote_id');
    }

    /**
     * Set quote_id
     * @param string $quote_id
     * @return \Vnecoms\Quotation\Api\Data\MessageInterface
     */
    public function setQuoteId($quote_id)
    {
        return $this->setData('quote_id', $quote_id);
    }

    /**
     * Set name
     * @param string $name
     * @return \Vnecoms\Quotation\Api\Data\MessageInterface
     */
    public function setName($name)
    {
        return $this->setData(self::NAME, $name);
    }

    /**
     * @return void
     */
    protected function _construct()
    {
        $this->_init('Vnecoms\Quotation\Model\ResourceModel\Message');
    }

    public function beforeSave()
    {
        if ($this->isObjectNew()) {
            $date = date("Y-m-d H:i:s", $this->timezone->scopeTimeStamp());
            $this->setCreatedAt($date);
        }
        if ($this->getQuote()) {
            $this->setQuoteId($this->getQuoteId());
        }
        return parent::beforeSave(); // TODO: Change the autogenerated stub
    }

    /**
     * Save attachment files
     * 
     * @return $this
     */
   public function afterSave()
   {
       parent::afterSave();
       $attachments = $this->getAttachments();
       if (!is_array($attachments)) return $this;
       foreach($attachments as $attachment){
           $attachmentObj = $this->getOm()->create('Vnecoms\Quotation\Model\Message\Attachment');
           $attachmentObj->setData([
               'message_id' => $this->getId(),
               'file_name' => $attachment,
           ])->save();
       }
   }

    /**
     * @return \Magento\Framework\App\ObjectManager
     */
    public function getOm()
    {
        return \Magento\Framework\App\ObjectManager::getInstance();
    }

    /**
     * @return \Vnecoms\Quotation\Model\Quote|null
     */
    public function getQuote()
    {
        if(!$this->quote && $this->getQuoteId()){
            $this->quote = ObjectManager::getInstance()
                ->create('Vnecoms\Quotation\Model\Quote')
                ->load($this->getQuoteId());
        }
        return $this->quote;
    }

    public function setQuote(\Vnecoms\Quotation\Model\Quote $quote)
    {
        $this->quote = $quote;
        $this->setQuoteId($quote->getQuoteId());
        return $this;
    }

    /**
     * @return string
     */
    public function getAttachments()
    {
        return $this->getData('attachments');
    }

    /**
     * @param $t
     * @return $this
     */
    public function setAttachment($t)
    {
        return $this->setData('attachments', $t);
    }
    
    /**
     * Get Attachment Collection
     * 
     * @return \Vnecoms\Quotation\Model\ResourceModel\Message\Attachment\Collection
     */
    public function getAttachmentCollection(){
        if(!$this->getData('attachment_collection')){
            $collection = $this->getOm()->create('Vnecoms\Quotation\Model\ResourceModel\Message\Attachment\Collection');
            $collection->addFieldToFilter('message_id', $this->getId())->setOrder('attachment_id','ASC');
            $this->setData('attachment_collection', $collection);
        }
        return $this->getData('attachment_collection');
    }
}
